#!/usr/bin/env python3
"""trim_ch5.py -- second pass on the assembled Chapter 5 (run after cut_ch5.py): tighten to ~10,000 words."""
import re
P = "/home/claude/work/src/docs/chapters/chapter5.md"
t = open(P, encoding="utf-8").read()
def sub1(old, new):
    global t
    assert t.count(old) == 1, (old[:70], t.count(old)); t = t.replace(old, new)
def replace_section(heading_prefix, new_text):
    """replace the whole section (heading through the line before the next heading) with new_text"""
    global t
    L = t.split("\n")
    a = next(k for k, l in enumerate(L) if l.startswith(heading_prefix))
    b = next((k for k, l in enumerate(L) if k > a and re.match(r"^#{2,3} ", l)), None)
    if b is None: b = next(k for k, l in enumerate(L) if k > a and l.startswith("**References Cited"))
    L[a:b] = new_text.strip("\n").split("\n") + [""]
    t = "\n".join(L)
def drop_table(caption_prefix):
    global t
    L = t.split("\n")
    a = next(k for k, l in enumerate(L) if l.startswith(caption_prefix))
    b = a + 1
    while b < len(L) and (L[b].startswith("|") or not L[b].strip()): b += 1
    del L[a:b]
    t = "\n".join(L)

